          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\r\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\r\n */\r\n//(1)==============================================================\r\nimport java.util.*;\r\nimport java.io.*;\r\n\r\npublic class MyList {\r\n  Node head,tail;\r\n  MyList() {head=tail=null;}\r\n  boolean isEmpty() {\r\n    return(head==null);\r\n   }\r\n  void clear() {head=tail=null;}\r\n\r\n  void fvisit(Node p, RandomAccessFile f) throws Exception {\r\n    if(p != null) f.writeBytes(p.info + \" \");\r\n   }\r\n\r\n  void ftraverse(RandomAccessFile f) throws Exception {\r\n    Node p = head;\r\n    while(p!=null) {\r\n       fvisit(p,f); // You will use this statement to write information of the node p to the file\r\n       p=p.next;\r\n      }\r\n    f.writeBytes(\"\\r\\n\");\r\n   }\r\n\r\n  void loadData(int k) { //do not edit this function\r\n    String [] a = Lib.readLineToStrArray(\"data.txt\", k);\r\n    int [] b = Lib.readLineToIntArray(\"data.txt\", k+1);\r\n    int [] c = Lib.readLineToIntArray(\"data.txt\", k+2);\r\n    int n = a.length;\r\n    for(int i=0;i<n;i++) addLast(a[i],b[i],c[i]);\r\n   }\r\n\r\n//===========================================================================\r\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\r\n//===========================================================================\r\n/* \r\n   Khong su dung tieng Viet co dau de viet ghi chu.\r\n   Neu dung khi chay truc tiep se bao loi va nhan 0 diem\r\n*/\r\n  void addLast(String xOwner, int xHorn, int xColor) {\r\n    //You should write here appropriate statements to complete this function.\r\n    if (xOwner.charAt(0) == 'A') return;\r\n    Cala c = new Cala(xOwner, xHorn, xColor);\r\n    Node node = new Node(c);\r\n    if (head == null) { head = tail = node; }\r\n    else { tail.next = node; tail = node; }\r\n   }\r\n\r\n  void insertAtPosition(Cala c, int pos) {\r\n    Node node = new Node(c);\r\n    if (pos == 0) {\r\n      node.next = head; head = node;\r\n      if (tail == null) tail = node;\r\n      return;\r\n    }\r\n    Node prev = head;\r\n    for (int i = 0; i < pos - 1; i++) prev = prev.next;\r\n    node.next = prev.next;\r\n    prev.next = node;\r\n    if (node.next == null) tail = node;\r\n   }\r\n\r\n  //You do not need to edit this function. Your task is to complete the addLast function above only.\r\n  void f1() throws Exception {\r\n     clear();\r\n     loadData(1);\r\n     String fname = \"f1.txt\";\r\n     File g123 = new File(fname);\r\n     if(g123.exists()) g123.delete();\r\n     RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n     ftraverse(f);\r\n     f.close();\r\n    }  \r\n\r\n//==================================================================\r\n  void f2() throws Exception {\r\n     clear();\r\n     loadData(5);\r\n     String fname = \"f2.txt\";\r\n     File g123 = new File(fname);\r\n     if(g123.exists()) g123.delete();\r\n     RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n     ftraverse(f);\r\n     Cala x, y, z;\r\n     x = new Cala(\"X\",1,2);\r\n     y = new Cala(\"Y\",2,3);\r\n     z = new Cala(\"Z\",3,4);\r\n     //------------------------------------------------------------------------------------\r\n     /*You must keep statements pre-given in this function.\r\n       Your task is to insert statements here, just after this comment,\r\n       to complete the question in the exam paper.*/\r\n     insertAtPosition(x, 1);\r\n     insertAtPosition(y, 4);\r\n     insertAtPosition(z, 6);\r\n    //------------------------------------------------------------------------------------\r\n     ftraverse(f);\r\n     f.close();\r\n    }  \r\n\r\n//==================================================================\r\n  void f3() throws Exception {\r\n    clear();\r\n    loadData(9);\r\n    String fname = \"f3.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    ftraverse(f);\r\n    //------------------------------------------------------------------------------------\r\n     /*You must keep statements pre-given in this function.\r\n       Your task is to insert statements here, just after this comment,\r\n       to complete the question in the exam paper.*/\r\n    Node p = null;\r\n    for (Node t = head; t != null; t = t.next) {\r\n      if (p == null || t.info.color > p.info.color) p = t;\r\n    }\r\n    if (p != null && p != tail) {\r\n      Cala tmp = tail.info;\r\n      tail.info = p.info;\r\n      p.info = tmp;\r\n    }\r\n    //------------------------------------------------------------------------------------\r\n    ftraverse(f);\r\n    f.close();\r\n  }\r\n\r\n//==================================================================\r\n  void f4() throws Exception {\r\n    clear();\r\n    loadData(13);\r\n    String fname = \"f4.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    ftraverse(f);\r\n    //------------------------------------------------------------------------------------\r\n     /*You must keep statements pre-given in this function.\r\n       Your task is to insert statements here, just after this comment,\r\n       to complete the question in the exam paper.*/\r\n    Node p = head;\r\n    while (p != null && !p.info.owner.equals(\"D\")) p = p.next;\r\n    if (p != null) {\r\n      java.util.ArrayList<Node> after = new java.util.ArrayList<Node>();\r\n      for (Node t = p.next; t != null && after.size() < 6; t = t.next) after.add(t);\r\n      java.util.ArrayList<Cala> vals = new java.util.ArrayList<Cala>();\r\n      for (Node n : after) vals.add(n.info);\r\n      vals.sort((a, b) -> a.color - b.color);\r\n      for (int i = 0; i < after.size(); i++) after.get(i).info = vals.get(i);\r\n    }\r\n    //------------------------------------------------------------------------------------\r\n    ftraverse(f);\r\n    f.close();\r\n   }\r\n\r\n }\r\n\r\n",
