          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\r\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\r\n */\r\n//(1)============================================\r\nimport java.io.*;\r\nimport java.util.*;\r\n//-------------------------------------------------------------------------------\r\npublic class Graph {\r\n  int [][] a; int n;\r\n  char v[];\r\n  int deg[];\r\n  Graph() {\r\n    v = \"ABCDEFGHIJKLMNOP\".toCharArray();\r\n    deg = new int[20];\r\n    a = new int[20][20];\r\n    n = 0;\r\n   }\r\n\r\n  void loadData(int k) {  //do not edit this function\r\n    RandomAccessFile f;int i,j,x;\r\n    String s;StringTokenizer t;\r\n    a = new int[20][20];\r\n    try {\r\n     f = new RandomAccessFile(\"data.txt\",\"r\");\r\n     for(i=0;i<k;i++) f.readLine();\r\n     s = f.readLine();s = s.trim();\r\n     n = Integer.parseInt(s);\r\n     for(i=0;i<n;i++) {\r\n       s = f.readLine();s = s.trim();\r\n       t = new StringTokenizer(s);\r\n       for(j=0;j<n;j++) { \r\n         x = Integer.parseInt(t.nextToken().trim());\r\n         a[i][j] = x;\r\n        }\r\n       }\r\n     f.close();\r\n     }\r\n    catch(Exception e) {}\r\n\r\n   }\r\n\r\n  void dispAdj() {\r\n    int i,j;\r\n    for(i=0;i<n;i++) {\r\n      System.out.println();\r\n      for(j=0;j<n;j++)\r\n        System.out.printf(\"%4d\",a[i][j]);\r\n     }\r\n   }\r\n\r\n  void fvisit(int i, RandomAccessFile f) throws Exception {\r\n    f.writeBytes(\"  \"+v[i]);\r\n   }\r\n  \r\n  /* There is an array int deg[] already declared in the class Graph \r\n     You should write a funcion to calculate d[i] = degree of the vertex i\r\n  */\r\n  void fvisitDeg(int i, RandomAccessFile f) throws Exception {\r\n    f.writeBytes(\"  \"+v[i]+\"(\"+deg[i]+\")\"); // d[i] = degree of the vertex i\r\n   }\r\n  \r\n void fdispAdj(RandomAccessFile f) throws Exception { \r\n    int i,j;\r\n    f.writeBytes(\"n = \"+n+\"\\r\\n\");\r\n    for(i=0;i<n;i++) {\r\n      f.writeBytes(\"\\r\\n\");\r\n      for(j=0;j<n;j++)  f.writeBytes(\"  \" + a[i][j]);\r\n     }\r\n    f.writeBytes(\"\\r\\n\");\r\n   }\r\n\r\n  void breadth(boolean [] en, int i, RandomAccessFile f) throws Exception {\r\n    Queue q = new Queue();\r\n    int r,j;\r\n    q.enqueue(i); en[i]=true;\r\n    while(!q.isEmpty()) {\r\n      r = q.dequeue();\r\n      fvisit(r,f);\r\n      for(j=0;j<n;j++) {\r\n        if(!en[j] && a[r][j]>0) {\r\n         q.enqueue(j);en[j]=true;\r\n        }\r\n       }\r\n     }\r\n   }\r\n\r\n  void breadth(int  k, RandomAccessFile f) throws Exception {\r\n    boolean [] en = new boolean[20];\r\n    int i;\r\n    for(i=0;i<n;i++) en[i]=false;\r\n    breadth(en,k,f);\r\n    for(i=0;i<n;i++) \r\n      if(!en[i]) breadth(en,i,f);\r\n   }\r\n\r\n void depth(boolean [] visited,int k, RandomAccessFile f) throws Exception {\r\n    fvisit(k,f);visited[k]=true;\r\n    for(int i=0;i<n;i++) {\r\n      if(!visited[i] && a[k][i]>0) depth(visited,i,f);\r\n     }\r\n   }\r\n  void depth(int k, RandomAccessFile f) throws Exception {\r\n    boolean [] visited = new boolean[20];\r\n    int i;\r\n    for(i=0;i<n;i++) visited[i]=false;\r\n    depth(visited,k,f);\r\n    for(i=0;i<n;i++) \r\n       if(!visited[i]) depth(visited,i,f);\r\n   }\r\n\r\n//===========================================================================\r\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\r\n//===========================================================================\r\n  void f1() throws Exception {\r\n    loadData(1);\r\n    String fname = \"f1.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    depth(4,f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    //-------------------------------------------------------------------------------------\r\n     /*You must keep statements pre-given in this function.\r\n       Your task is to insert statements here, just after this comment,\r\n       to complete the question in the exam paper.*/\r\n    for (int i = 0; i < n; i++) {\r\n      int d = 0;\r\n      for (int j = 0; j < n; j++) if (a[i][j] > 0) d++;\r\n      deg[i] = d;\r\n    }\r\n    java.util.ArrayList<Integer> order = new java.util.ArrayList<Integer>();\r\n    boolean[] visited2 = new boolean[20];\r\n    depth2(visited2, 4, order);\r\n    for (int i = 0; i < n; i++) if (!visited2[i]) depth2(visited2, i, order);\r\n    for (int idx = 1; idx <= 6 && idx < order.size(); idx++) {\r\n      fvisitDeg(order.get(idx), f);\r\n    }\r\n    //-------------------------------------------------------------------------------------\r\n    f.writeBytes(\"\\r\\n\");\r\n    f.close();\r\n   }\r\n\r\n  void depth2(boolean[] visited, int k, java.util.ArrayList<Integer> order) {\r\n    order.add(k); visited[k] = true;\r\n    for (int i = 0; i < n; i++) {\r\n      if (!visited[i] && a[k][i] > 0) depth2(visited, i, order);\r\n    }\r\n   }\r\n\r\n//=================================================================================================\r\n  void f2() throws Exception {\r\n    loadData(12);\r\n    String fname = \"f2.txt\";\r\n    File g123 = new File(fname);\r\n    if(g123.exists()) g123.delete();\r\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \r\n    //-------------------------------------------------------------------------------------\r\n     /*You must keep statements pre-given in this function.\r\n       Your task is to insert statements here, just after this comment,\r\n       to complete the question in the exam paper.*/\r\n      // You can use the statement fvisit(i,f); i = 0, 1, 2,...,n-1 to display the vertex i to file f2.txt \r\n      //  and statement f.writeBytes(\" \" + k); to write  variable k to the file f2.txt\r\n    int[] parent = new int[n];\r\n    java.util.ArrayList<Integer> order = new java.util.ArrayList<Integer>();\r\n    java.util.ArrayList<Integer> distOrder = new java.util.ArrayList<Integer>();\r\n    int targetDist = dijkstra(0, 6, parent, order, distOrder);\r\n    int startLast4 = Math.max(0, order.size() - 4);\r\n    for (int idx = startLast4; idx < order.size(); idx++) fvisit(order.get(idx), f);\r\n    f.writeBytes(\"\\r\\n\");\r\n    for (int idx = startLast4; idx < order.size(); idx++) f.writeBytes(\" \" + distOrder.get(idx));\r\n    f.writeBytes(\"\\r\\n\");\r\n    java.util.ArrayList<Integer> path = buildPath(parent, 0, 6);\r\n    f.writeBytes(\"\" + targetDist);\r\n    fvisit(path.get(0), f);\r\n    fvisit(path.get(3), f);\r\n    fvisit(path.get(path.size() - 1), f);\r\n    //-------------------------------------------------------------------------------------\r\n    f.writeBytes(\"\\r\\n\");\r\n    f.close();\r\n   }\r\n\r\n  int dijkstra(int src, int target, int[] parent, java.util.ArrayList<Integer> order, java.util.ArrayList<Integer> distOrder) {\r\n    int[] dist = new int[n];\r\n    boolean[] visited = new boolean[n];\r\n    for (int i = 0; i < n; i++) { dist[i] = Integer.MAX_VALUE / 2; parent[i] = -1; }\r\n    dist[src] = 0;\r\n    for (int iter = 0; iter < n; iter++) {\r\n      int u = -1, best = Integer.MAX_VALUE;\r\n      for (int i = 0; i < n; i++) if (!visited[i] && dist[i] < best) { best = dist[i]; u = i; }\r\n      if (u == -1) break;\r\n      visited[u] = true;\r\n      order.add(u);\r\n      distOrder.add(dist[u]);\r\n      if (u == target) break;\r\n      for (int w = 0; w < n; w++) {\r\n        int wt = a[u][w];\r\n        if (wt < 99 && wt > 0 && !visited[w] && dist[u] + wt < dist[w]) {\r\n          dist[w] = dist[u] + wt;\r\n          parent[w] = u;\r\n        }\r\n      }\r\n    }\r\n    return dist[target];\r\n   }\r\n\r\n  java.util.ArrayList<Integer> buildPath(int[] parent, int src, int dst) {\r\n    java.util.ArrayList<Integer> p = new java.util.ArrayList<Integer>();\r\n    int cur = dst;\r\n    while (cur != -1) {\r\n      p.add(0, cur);\r\n      if (cur == src) break;\r\n      cur = parent[cur];\r\n    }\r\n    return p;\r\n   }\r\n\r\n}\r\n",
